#!/usr/bin/env node
/**
 * Generates the frontend's contract ABIs and deployment file from the contracts workspace.
 *
 *   npm run gen:abis              forge build, then write src/generated/*
 *   npm run gen:abis -- --no-build   reuse an existing contracts/out
 *
 * Writes:
 *   src/generated/abis.ts     ABIs taken from contracts/out/<Name>.sol/<Name>.json
 *   src/generated/current.json  copy of contracts/deployments/current.json (an empty stub if none exists yet)
 *
 * The generated files are committed so the Vercel build does not need Foundry.
 */
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const frontendDir = path.resolve(import.meta.dirname, "..");
const contractsDir = path.resolve(frontendDir, "..", "contracts");
const outDir = path.join(frontendDir, "src", "generated");

/** Contract name -> exported constant name. */
const CONTRACTS = {
  QuantumRound: "quantumRoundAbi",
  WaveV4ProposalMarket: "marketAbi",
  WavefundVault: "vaultAbi",
  ProposerRegistry: "registryAbi",
  ProposalTokens: "proposalTokensAbi",
  MockPriceOracle: "oracleAbi",
};

const skipBuild = process.argv.includes("--no-build");

if (!skipBuild) {
  console.log("forge build (tests and scripts skipped)...");
  const res = spawnSync("forge", ["build", "--skip", "test", "--skip", "script"], {
    cwd: contractsDir,
    stdio: "inherit",
  });
  if (res.status !== 0) {
    console.error("forge build failed. Fix the build, or run with --no-build to reuse contracts/out.");
    process.exit(res.status ?? 1);
  }
}

fs.mkdirSync(outDir, { recursive: true });

let source = "// Generated by scripts/gen-abis.mjs from the forge build. Do not edit by hand.\n\n";
for (const [name, exportName] of Object.entries(CONTRACTS)) {
  const artifact = path.join(contractsDir, "out", `${name}.sol`, `${name}.json`);
  if (!fs.existsSync(artifact)) {
    console.error(`Missing artifact for ${name}: ${artifact}`);
    process.exit(1);
  }
  const { abi } = JSON.parse(fs.readFileSync(artifact, "utf8"));
  source += `export const ${exportName} = ${JSON.stringify(abi, null, 2)} as const;\n\n`;
  console.log(`  ${name}: ${abi.length} ABI entries`);
}
fs.writeFileSync(path.join(outDir, "abis.ts"), source);

const deploymentSrc = path.join(contractsDir, "deployments", "current.json");
const deploymentDst = path.join(outDir, "current.json");
if (fs.existsSync(deploymentSrc)) {
  fs.copyFileSync(deploymentSrc, deploymentDst);
  console.log("Copied contracts/deployments/current.json");
} else if (!fs.existsSync(deploymentDst)) {
  fs.writeFileSync(deploymentDst, JSON.stringify({ chainId: 5042002, contracts: {} }, null, 2) + "\n");
  console.log("No deployment found yet: wrote an empty src/generated/current.json");
} else {
  console.log("No contracts/deployments/current.json: kept the existing src/generated/current.json");
}
